#!/usr/bin/env python3
"""Setup script — Portal CREAR. Ejecutar desde cualquier carpeta."""
import os, sys

BASE = "portal-crear"
if os.path.exists(BASE):
    print(f"Error: la carpeta '{BASE}' ya existe.")
    sys.exit(1)

FILES = {
  "package.json": '{\n  "name": "portal-crear",\n  "private": true,\n  "version": "0.0.0",\n  "type": "module",\n  "scripts": {\n    "dev": "vite",\n    "build": "vite build",\n    "preview": "vite preview"\n  },\n  "dependencies": {\n    "@supabase/supabase-js": "^2.39.0",\n    "lucide-react": "^0.344.0",\n    "react": "^18.2.0",\n    "react-dom": "^18.2.0",\n    "react-router-dom": "^6.21.0"\n  },\n  "devDependencies": {\n    "@vitejs/plugin-react": "^4.2.1",\n    "autoprefixer": "^10.4.16",\n    "postcss": "^8.4.32",\n    "tailwindcss": "^3.4.0",\n    "vite": "^5.0.0",\n    "vite-plugin-pwa": "^0.19.0"\n  }\n}\n',
  "index.html": '<!doctype html>\n<html lang="es">\n  <head>\n    <meta charset="UTF-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />\n    <meta name="theme-color" content="#7C3AED" />\n    <meta name="apple-mobile-web-app-capable" content="yes" />\n    <meta name="apple-mobile-web-app-status-bar-style" content="default" />\n    <meta name="apple-mobile-web-app-title" content="CREAR" />\n    <title>CREAR — Portal Familiar</title>\n    <link rel="preconnect" href="https://fonts.googleapis.com" />\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />\n    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,600;1,400&display=swap" rel="stylesheet" />\n  </head>\n  <body>\n    <div id="root"></div>\n    <script type="module" src="/src/main.jsx"></script>\n  </body>\n</html>\n',
  "vite.config.js": "import { defineConfig } from 'vite'\nimport react from '@vitejs/plugin-react'\nimport { VitePWA } from 'vite-plugin-pwa'\n\nexport default defineConfig({\n  plugins: [\n    react(),\n    VitePWA({\n      registerType: 'autoUpdate',\n      includeAssets: ['logo.png'],\n      manifest: {\n        name: 'CREAR — Portal Familiar',\n        short_name: 'CREAR',\n        description: 'Información para alumnos y familias de la Academia de Danzas CREAR',\n        theme_color: '#7C3AED',\n        background_color: '#F4F2FF',\n        display: 'standalone',\n        orientation: 'portrait',\n        start_url: '/',\n        icons: [\n          { src: 'pwa-192.png', sizes: '192x192', type: 'image/png' },\n          { src: 'pwa-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' },\n        ],\n      },\n      workbox: {\n        globPatterns: ['**/*.{js,css,html,ico,png,svg}'],\n      },\n    }),\n  ],\n})\n",
  "tailwind.config.js": "/** @type {import('tailwindcss').Config} */\nexport default {\n  content: ['./index.html', './src/**/*.{js,jsx}'],\n  theme: {\n    extend: {\n      colors: {\n        primary: '#7C3AED',\n        'primary-dark': '#6D28D9',\n        'primary-light': '#EDE9FE',\n        'primary-subtle': '#F4F2FF',\n        teal: '#0D9488',\n        'teal-dark': '#0F766E',\n        'teal-light': '#CCFBF1',\n      },\n      fontFamily: {\n        sans: ['Inter', 'system-ui', 'sans-serif'],\n        display: ['\"Playfair Display\"', 'Georgia', 'serif'],\n      },\n      boxShadow: {\n        card: '0 1px 4px 0 rgb(0 0 0 / 0.06)',\n        'card-md': '0 4px 16px 0 rgb(124 58 237 / 0.12)',\n      },\n      animation: {\n        'fade-up': 'fadeUp 0.3s ease-out both',\n      },\n      keyframes: {\n        fadeUp: {\n          '0%': { opacity: '0', transform: 'translateY(8px)' },\n          '100%': { opacity: '1', transform: 'translateY(0)' },\n        },\n      },\n    },\n  },\n  plugins: [],\n}\n",
  "postcss.config.js": "export default {\n  plugins: {\n    tailwindcss: {},\n    autoprefixer: {},\n  },\n}\n",
  ".gitignore": "node_modules\ndist\n.env\n.env.local\n",
  ".env.example": "VITE_SUPABASE_URL=https://umyxrehjchxlxtdibaii.supabase.co\nVITE_SUPABASE_ANON_KEY=sb_publishable_9IVvZSsjFPvtak80-_ZGEg_nKYn95vr\n",
  "src/index.css": "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n@layer base {\n  body {\n    font-family: 'Inter', system-ui, sans-serif;\n    background-color: #F4F2FF;\n    color: #1E1B4B;\n    -webkit-font-smoothing: antialiased;\n    -moz-osx-font-smoothing: grayscale;\n    margin: 0;\n  }\n  #root { min-height: 100svh; }\n  *::-webkit-scrollbar { width: 4px; }\n  *::-webkit-scrollbar-track { background: transparent; }\n  *::-webkit-scrollbar-thumb { background: #C4B5FD; border-radius: 99px; }\n}\n\n.pb-safe { padding-bottom: max(env(safe-area-inset-bottom), 16px); }\n.pt-safe { padding-top: env(safe-area-inset-top, 0px); }\n",
  "src/main.jsx": "import { createRoot } from 'react-dom/client'\nimport './index.css'\nimport App from './App.jsx'\n\ncreateRoot(document.getElementById('root')).render(<App />)\n",
  "src/App.jsx": "import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom'\nimport { AuthProvider, useAuth } from './context/AuthContext'\nimport TopBar from './components/TopBar'\nimport BottomNav from './components/BottomNav'\nimport Login from './pages/Login'\nimport Home from './pages/Home'\nimport Pagos from './pages/Pagos'\nimport Asistencia from './pages/Asistencia'\nimport Grupos from './pages/Grupos'\nimport Evaluaciones from './pages/Evaluaciones'\n\nconst pageTitles = {\n  '/home':         'Inicio',\n  '/pagos':        'Pagos',\n  '/asistencia':   'Asistencia',\n  '/grupos':       'Mis grupos',\n  '/evaluaciones': 'Evaluaciones',\n}\n\nfunction ProtectedLayout() {\n  const { alumno } = useAuth()\n  const path = window.location.pathname\n  if (!alumno) return <Navigate to=\"/login\" replace />\n  return (\n    <div className=\"flex flex-col h-svh max-w-md mx-auto\">\n      <TopBar title={pageTitles[path] ?? 'CREAR'} />\n      <main className=\"flex-1 overflow-y-auto bg-primary-subtle\">\n        <Routes>\n          <Route path=\"/home\"         element={<Home />} />\n          <Route path=\"/pagos\"        element={<Pagos />} />\n          <Route path=\"/asistencia\"   element={<Asistencia />} />\n          <Route path=\"/grupos\"       element={<Grupos />} />\n          <Route path=\"/evaluaciones\" element={<Evaluaciones />} />\n          <Route path=\"*\"             element={<Navigate to=\"/home\" replace />} />\n        </Routes>\n      </main>\n      <BottomNav />\n    </div>\n  )\n}\n\nfunction PublicRoute() {\n  const { alumno } = useAuth()\n  if (alumno) return <Navigate to=\"/home\" replace />\n  return <Login />\n}\n\nexport default function App() {\n  return (\n    <AuthProvider>\n      <BrowserRouter>\n        <Routes>\n          <Route path=\"/login\" element={<PublicRoute />} />\n          <Route path=\"/*\"     element={<ProtectedLayout />} />\n        </Routes>\n      </BrowserRouter>\n    </AuthProvider>\n  )\n}\n",
  "src/lib/supabase.js": "import { createClient } from '@supabase/supabase-js'\n\nconst url = import.meta.env.VITE_SUPABASE_URL\nconst key = import.meta.env.VITE_SUPABASE_ANON_KEY\n\nexport const supabase = createClient(url, key)\n",
  "src/context/AuthContext.jsx": "import { createContext, useContext, useState, useCallback } from 'react'\n\nconst AuthContext = createContext(null)\nconst STORAGE_KEY = 'crear_portal_alumno'\n\nfunction loadSaved() {\n  try { return JSON.parse(localStorage.getItem(STORAGE_KEY)) ?? null } catch { return null }\n}\n\nexport function AuthProvider({ children }) {\n  const [alumno, setAlumno] = useState(loadSaved)\n  const login = useCallback((data) => {\n    localStorage.setItem(STORAGE_KEY, JSON.stringify(data))\n    setAlumno(data)\n  }, [])\n  const logout = useCallback(() => {\n    localStorage.removeItem(STORAGE_KEY)\n    setAlumno(null)\n  }, [])\n  return <AuthContext.Provider value={{ alumno, login, logout }}>{children}</AuthContext.Provider>\n}\n\nexport function useAuth() { return useContext(AuthContext) }\n",
  "src/services/auth.js": "import { supabase } from '../lib/supabase'\n\nexport async function loginByDni(dni, fechaNacimiento) {\n  const { data, error } = await supabase\n    .from('alumnos')\n    .select('id, nombre, apellido, dni, fecha_nacimiento')\n    .eq('dni', dni.trim())\n    .single()\n  if (error || !data) throw new Error('DNI no encontrado en el sistema.')\n  if (data.fecha_nacimiento !== fechaNacimiento)\n    throw new Error('La fecha de nacimiento no coincide.')\n  return { id: data.id, nombre: data.nombre, apellido: data.apellido }\n}\n",
  "src/services/portal.js": "import { supabase } from '../lib/supabase'\n\nexport async function getCuotas(alumnoId) {\n  const { data, error } = await supabase\n    .from('cuotas').select('id, mes, monto, estado, fecha_vencimiento, fecha_pago')\n    .eq('alumno_id', alumnoId).order('mes', { ascending: false })\n  if (error) throw error\n  return data ?? []\n}\n\nexport async function getInscripciones(alumnoId) {\n  const { data: insc, error } = await supabase\n    .from('inscripciones').select('id, estado, fecha, grupo_id')\n    .eq('alumno_id', alumnoId).eq('estado', 'activa')\n  if (error) throw error\n  const grupoIds = (insc ?? []).map((i) => i.grupo_id)\n  if (!grupoIds.length) return []\n  const { data: grupos } = await supabase\n    .from('grupos').select('id, nombre, nivel, dia, horario, disciplina').in('id', grupoIds)\n  const gruposMap = Object.fromEntries((grupos ?? []).map((g) => [g.id, g]))\n  return (insc ?? []).map((i) => ({ ...i, grupo: gruposMap[i.grupo_id] ?? null }))\n}\n\nexport async function getAsistencia(alumnoId) {\n  const { data, error } = await supabase\n    .from('asistencias').select('id, fecha, presente, grupo_id')\n    .eq('alumno_id', alumnoId).order('fecha', { ascending: false }).limit(30)\n  if (error) throw error\n  const grupoIds = [...new Set((data ?? []).map((a) => a.grupo_id))]\n  if (!grupoIds.length) return []\n  const { data: grupos } = await supabase.from('grupos').select('id, nombre').in('id', grupoIds)\n  const gruposMap = Object.fromEntries((grupos ?? []).map((g) => [g.id, g]))\n  return (data ?? []).map((a) => ({ ...a, grupo: gruposMap[a.grupo_id] ?? null }))\n}\n\nexport async function getEvaluaciones(alumnoId) {\n  const { data, error } = await supabase\n    .from('evaluaciones').select('id, fecha, nota, observaciones, grupo_id')\n    .eq('alumno_id', alumnoId).order('fecha', { ascending: false })\n  if (error) throw error\n  const grupoIds = [...new Set((data ?? []).map((e) => e.grupo_id))]\n  if (!grupoIds.length) return []\n  const { data: grupos } = await supabase.from('grupos').select('id, nombre').in('id', grupoIds)\n  const gruposMap = Object.fromEntries((grupos ?? []).map((g) => [g.id, g]))\n  return (data ?? []).map((e) => ({ ...e, grupo: gruposMap[e.grupo_id] ?? null }))\n}\n",
  "src/components/TopBar.jsx": "import { LogOut } from 'lucide-react'\nimport { useAuth } from '../context/AuthContext'\nimport { useNavigate } from 'react-router-dom'\n\nexport default function TopBar({ title }) {\n  const { alumno, logout } = useAuth()\n  const navigate = useNavigate()\n  function handleLogout() { logout(); navigate('/login', { replace: true }) }\n  return (\n    <header className=\"bg-white border-b border-[#EDE9FE] px-4 h-14 flex items-center justify-between shrink-0 sticky top-0 z-10\">\n      <div className=\"flex items-center gap-2.5\">\n        <div className=\"w-7 h-7 rounded-lg flex items-center justify-center shrink-0\"\n          style={{ background: 'linear-gradient(135deg, #7C3AED, #A78BFA)' }}>\n          <span className=\"text-white text-[10px] font-black\">C</span>\n        </div>\n        <span className=\"text-sm font-bold text-[#1E1B4B]\">{title}</span>\n      </div>\n      <div className=\"flex items-center gap-2\">\n        {alumno && <span className=\"text-xs text-[#A89FC8] hidden sm:block\">{alumno.apellido}, {alumno.nombre}</span>}\n        <button onClick={handleLogout} className=\"w-8 h-8 flex items-center justify-center rounded-xl text-[#A89FC8] hover:bg-[#F4F2FF] hover:text-primary transition-colors\">\n          <LogOut size={15} />\n        </button>\n      </div>\n    </header>\n  )\n}\n",
  "src/components/BottomNav.jsx": "import { NavLink } from 'react-router-dom'\nimport { Home, CreditCard, CalendarCheck, UsersRound, Star } from 'lucide-react'\n\nconst items = [\n  { to: '/home', icon: Home, label: 'Inicio' },\n  { to: '/pagos', icon: CreditCard, label: 'Pagos' },\n  { to: '/asistencia', icon: CalendarCheck, label: 'Asistencia' },\n  { to: '/grupos', icon: UsersRound, label: 'Grupos' },\n  { to: '/evaluaciones', icon: Star, label: 'Notas' },\n]\n\nexport default function BottomNav() {\n  return (\n    <nav className=\"bg-white border-t border-[#EDE9FE] pb-safe shrink-0\">\n      <div className=\"flex\">\n        {items.map(({ to, icon: Icon, label }) => (\n          <NavLink key={to} to={to}\n            className={({ isActive }) => `flex-1 flex flex-col items-center gap-1 py-2.5 transition-colors ${isActive ? 'text-primary' : 'text-[#A89FC8]'}`}\n          >\n            {({ isActive }) => (\n              <>\n                <div className={`p-1.5 rounded-xl transition-colors ${isActive ? 'bg-primary-light' : ''}`}><Icon size={18} /></div>\n                <span className=\"text-[10px] font-semibold leading-none\">{label}</span>\n              </>\n            )}\n          </NavLink>\n        ))}\n      </div>\n    </nav>\n  )\n}\n",
  "src/components/ui/Badge.jsx": "const COLORS = {\n  green:  { cls: 'bg-emerald-50 text-emerald-700 ring-1 ring-emerald-200', dot: 'bg-emerald-400' },\n  red:    { cls: 'bg-red-50 text-red-600 ring-1 ring-red-200',             dot: 'bg-red-400' },\n  yellow: { cls: 'bg-amber-50 text-amber-700 ring-1 ring-amber-200',       dot: 'bg-amber-400' },\n  blue:   { cls: 'bg-primary-light text-primary ring-1 ring-purple-200',   dot: 'bg-primary' },\n  teal:   { cls: 'bg-teal-light text-teal-dark ring-1 ring-teal/30',       dot: 'bg-teal' },\n  gray:   { cls: 'bg-gray-100 text-gray-500 ring-1 ring-gray-200',         dot: 'bg-gray-400' },\n}\n\nexport default function Badge({ children, color = 'gray', dot = false, className = '' }) {\n  const { cls, dot: dotColor } = COLORS[color] ?? COLORS.gray\n  return (\n    <span className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold ${cls} ${className}`}>\n      {dot && <span className={`w-1.5 h-1.5 rounded-full shrink-0 ${dotColor}`} />}\n      {children}\n    </span>\n  )\n}\n",
  "src/components/ui/Spinner.jsx": "export default function Spinner({ className = '' }) {\n  return (\n    <div className={`flex justify-center items-center ${className}`}>\n      <div className=\"w-8 h-8 border-[3px] border-primary-light border-t-primary rounded-full animate-spin\" />\n    </div>\n  )\n}\n",
  "src/pages/Login.jsx": "import { useState } from 'react'\nimport { useNavigate } from 'react-router-dom'\nimport { loginByDni } from '../services/auth'\nimport { useAuth } from '../context/AuthContext'\n\nexport default function Login() {\n  const [dni, setDni] = useState('')\n  const [fecha, setFecha] = useState('')\n  const [error, setError] = useState('')\n  const [loading, setLoading] = useState(false)\n  const { login } = useAuth()\n  const navigate = useNavigate()\n\n  async function handleSubmit(e) {\n    e.preventDefault()\n    setError('')\n    setLoading(true)\n    try {\n      const alumno = await loginByDni(dni, fecha)\n      login(alumno)\n      navigate('/home', { replace: true })\n    } catch (err) {\n      setError(err.message)\n    } finally {\n      setLoading(false)\n    }\n  }\n\n  return (\n    <div className=\"min-h-svh flex flex-col items-center justify-center px-6 py-12\"\n      style={{ background: 'linear-gradient(160deg, #2E1065 0%, #3B0764 60%, #F4F2FF 100%)' }}>\n      <div className=\"flex flex-col items-center mb-10\">\n        <div className=\"w-16 h-16 rounded-2xl bg-white/15 border border-white/25 flex items-center justify-center mb-4 backdrop-blur-sm\">\n          <span className=\"text-white font-black text-2xl font-display\">C</span>\n        </div>\n        <h1 className=\"text-white font-bold text-2xl tracking-wide font-display\">CREAR</h1>\n        <p className=\"text-white/50 text-xs tracking-widest uppercase mt-1\">Portal Familiar</p>\n      </div>\n      <div className=\"w-full max-w-sm bg-white rounded-3xl shadow-card-md p-7\">\n        <h2 className=\"text-[15px] font-bold text-[#1E1B4B] mb-1\">Ingresá a tu cuenta</h2>\n        <p className=\"text-xs text-[#A89FC8] mb-6\">Usá el DNI y la fecha de nacimiento del alumno</p>\n        <form onSubmit={handleSubmit} className=\"space-y-4\">\n          <div>\n            <label className=\"block text-xs font-semibold text-[#1E1B4B] mb-1.5\">DNI del alumno</label>\n            <input type=\"text\" inputMode=\"numeric\" value={dni} onChange={(e) => setDni(e.target.value)}\n              placeholder=\"Ej: 40123456\" required\n              className=\"w-full px-4 py-3 rounded-xl border border-[#EDE9FE] bg-[#F9F7FF] text-sm text-[#1E1B4B] placeholder-[#C4B5FD] focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition\" />\n          </div>\n          <div>\n            <label className=\"block text-xs font-semibold text-[#1E1B4B] mb-1.5\">Fecha de nacimiento</label>\n            <input type=\"date\" value={fecha} onChange={(e) => setFecha(e.target.value)} required\n              className=\"w-full px-4 py-3 rounded-xl border border-[#EDE9FE] bg-[#F9F7FF] text-sm text-[#1E1B4B] focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition\" />\n          </div>\n          {error && <p className=\"text-xs text-red-600 bg-red-50 border border-red-200 rounded-xl px-4 py-2.5\">{error}</p>}\n          <button type=\"submit\" disabled={loading}\n            className=\"w-full py-3 rounded-xl bg-primary text-white font-semibold text-sm hover:bg-primary-dark active:scale-[.98] transition-all disabled:opacity-60 disabled:cursor-not-allowed shadow-card-md\">\n            {loading ? 'Verificando...' : 'Ingresar'}\n          </button>\n        </form>\n      </div>\n      <p className=\"text-white/25 text-[10px] mt-8 text-center\">Academia de Danzas CREAR · Tesis 2025</p>\n    </div>\n  )\n}\n",
  "src/pages/Home.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getCuotas, getInscripciones } from '../services/portal'\nimport Badge from '../components/ui/Badge'\nimport Spinner from '../components/ui/Spinner'\nimport { CreditCard, UsersRound, AlertCircle, CheckCircle2 } from 'lucide-react'\n\nfunction estadoBadge(estado) {\n  if (estado === 'pagada') return <Badge color=\"teal\" dot>Pagada</Badge>\n  if (estado === 'vencida') return <Badge color=\"red\" dot>Vencida</Badge>\n  return <Badge color=\"yellow\" dot>Pendiente</Badge>\n}\n\nexport default function Home() {\n  const { alumno } = useAuth()\n  const [cuotas, setCuotas] = useState([])\n  const [grupos, setGrupos] = useState([])\n  const [loading, setLoading] = useState(true)\n\n  useEffect(() => {\n    async function cargar() {\n      try {\n        const [c, g] = await Promise.all([getCuotas(alumno.id), getInscripciones(alumno.id)])\n        setCuotas(c); setGrupos(g)\n      } finally { setLoading(false) }\n    }\n    cargar()\n  }, [alumno.id])\n\n  const pendientes = cuotas.filter((c) => c.estado !== 'pagada').length\n  const ultimaCuota = cuotas[0]\n  if (loading) return <Spinner className=\"mt-20\" />\n\n  return (\n    <div className=\"px-4 py-5 space-y-5 animate-fade-up\">\n      <div className=\"rounded-2xl p-5 shadow-card\" style={{ background: 'linear-gradient(135deg, #2E1065, #7C3AED)' }}>\n        <p className=\"text-white/60 text-xs font-medium\">Hola,</p>\n        <h2 className=\"text-white font-bold text-xl font-display mt-0.5\">{alumno.nombre} {alumno.apellido}</h2>\n        <p className=\"text-white/50 text-xs mt-2\">{grupos.length > 0 ? `Inscripta en ${grupos.length} grupo${grupos.length > 1 ? 's' : ''}` : 'Sin grupos activos'}</p>\n      </div>\n      <div className=\"grid grid-cols-2 gap-3\">\n        <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card\">\n          <div className=\"w-9 h-9 bg-primary-light rounded-xl flex items-center justify-center mb-3\"><UsersRound size={16} className=\"text-primary\" /></div>\n          <p className=\"text-2xl font-black text-primary\">{grupos.length}</p>\n          <p className=\"text-xs text-[#A89FC8] mt-0.5\">Grupos activos</p>\n        </div>\n        <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card\">\n          <div className={`w-9 h-9 rounded-xl flex items-center justify-center mb-3 ${pendientes > 0 ? 'bg-amber-50' : 'bg-teal-light'}`}>\n            {pendientes > 0 ? <AlertCircle size={16} className=\"text-amber-500\" /> : <CheckCircle2 size={16} className=\"text-teal\" />}\n          </div>\n          <p className={`text-2xl font-black ${pendientes > 0 ? 'text-amber-500' : 'text-teal'}`}>{pendientes}</p>\n          <p className=\"text-xs text-[#A89FC8] mt-0.5\">Cuotas pendientes</p>\n        </div>\n      </div>\n      {ultimaCuota && (\n        <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-5 shadow-card\">\n          <div className=\"flex items-center gap-2 mb-4\"><div className=\"p-2 bg-primary-light rounded-xl\"><CreditCard size={14} className=\"text-primary\" /></div><p className=\"text-sm font-bold text-[#1E1B4B]\">Última cuota</p></div>\n          <div className=\"flex items-center justify-between\">\n            <div>\n              <p className=\"text-sm font-semibold text-[#1E1B4B] capitalize\">{new Date(ultimaCuota.mes + '-01T00:00:00').toLocaleDateString('es-AR', { month: 'long', year: 'numeric' })}</p>\n              <p className=\"text-xs text-[#A89FC8] mt-0.5\">Vence: {ultimaCuota.fecha_vencimiento ? new Date(ultimaCuota.fecha_vencimiento + 'T00:00:00').toLocaleDateString('es-AR') : '—'}</p>\n            </div>\n            <div className=\"text-right\"><p className=\"text-lg font-black text-[#1E1B4B]\">${Number(ultimaCuota.monto).toLocaleString('es-AR')}</p><div className=\"mt-1\">{estadoBadge(ultimaCuota.estado)}</div></div>\n          </div>\n        </div>\n      )}\n      {grupos.length > 0 && (\n        <div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-5 shadow-card\">\n          <p className=\"text-sm font-bold text-[#1E1B4B] mb-3\">Mis grupos</p>\n          <ul className=\"space-y-2\">\n            {grupos.map((i) => (\n              <li key={i.id} className=\"flex items-center gap-3 p-2.5 rounded-xl bg-[#F9F7FF]\">\n                <div className=\"w-8 h-8 bg-primary-light rounded-xl flex items-center justify-center shrink-0\"><UsersRound size={14} className=\"text-primary\" /></div>\n                <div><p className=\"text-sm font-semibold text-[#1E1B4B]\">{i.grupo?.nombre ?? '—'}</p><p className=\"text-xs text-[#A89FC8]\">{i.grupo?.nivel} · {i.grupo?.dia} {i.grupo?.horario}</p></div>\n              </li>\n            ))}\n          </ul>\n        </div>\n      )}\n    </div>\n  )\n}\n",
  "src/pages/Pagos.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getCuotas } from '../services/portal'\nimport Badge from '../components/ui/Badge'\nimport Spinner from '../components/ui/Spinner'\nimport { CreditCard } from 'lucide-react'\n\nfunction badgeColor(e) { return e === 'pagada' ? 'teal' : e === 'vencida' ? 'red' : 'yellow' }\nfunction mesLabel(mes) { return new Date(mes + '-01T00:00:00').toLocaleDateString('es-AR', { month: 'long', year: 'numeric' }) }\n\nexport default function Pagos() {\n  const { alumno } = useAuth()\n  const [cuotas, setCuotas] = useState([])\n  const [loading, setLoading] = useState(true)\n  useEffect(() => { getCuotas(alumno.id).then(setCuotas).finally(() => setLoading(false)) }, [alumno.id])\n  if (loading) return <Spinner className=\"mt-20\" />\n  const pendientes = cuotas.filter((c) => c.estado !== 'pagada')\n  const pagadas = cuotas.filter((c) => c.estado === 'pagada')\n  return (\n    <div className=\"px-4 py-5 space-y-4 animate-fade-up\">\n      <h2 className=\"text-base font-bold text-[#1E1B4B]\">Pagos y cuotas</h2>\n      {pendientes.length > 0 && (<div><p className=\"text-xs font-semibold text-[#A89FC8] uppercase tracking-wider mb-2 px-1\">Pendientes</p><ul className=\"space-y-2\">{pendientes.map((c) => (<li key={c.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card flex items-center justify-between\"><div className=\"flex items-center gap-3\"><div className=\"w-9 h-9 bg-amber-50 rounded-xl flex items-center justify-center shrink-0\"><CreditCard size={15} className=\"text-amber-500\" /></div><div><p className=\"text-sm font-semibold text-[#1E1B4B] capitalize\">{mesLabel(c.mes)}</p><p className=\"text-xs text-[#A89FC8]\">Vence: {c.fecha_vencimiento ? new Date(c.fecha_vencimiento + 'T00:00:00').toLocaleDateString('es-AR') : '—'}</p></div></div><div className=\"text-right\"><p className=\"text-sm font-black text-[#1E1B4B]\">${Number(c.monto).toLocaleString('es-AR')}</p><Badge color={badgeColor(c.estado)} dot className=\"mt-1\">{c.estado}</Badge></div></li>))}</ul></div>)}\n      {pagadas.length > 0 && (<div><p className=\"text-xs font-semibold text-[#A89FC8] uppercase tracking-wider mb-2 px-1\">Historial pagado</p><ul className=\"space-y-2\">{pagadas.map((c) => (<li key={c.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card flex items-center justify-between opacity-75\"><div className=\"flex items-center gap-3\"><div className=\"w-9 h-9 bg-teal-light rounded-xl flex items-center justify-center shrink-0\"><CreditCard size={15} className=\"text-teal\" /></div><div><p className=\"text-sm font-semibold text-[#1E1B4B] capitalize\">{mesLabel(c.mes)}</p><p className=\"text-xs text-[#A89FC8]\">Pagado: {c.fecha_pago ? new Date(c.fecha_pago + 'T00:00:00').toLocaleDateString('es-AR') : '—'}</p></div></div><div className=\"text-right\"><p className=\"text-sm font-black text-[#1E1B4B]\">${Number(c.monto).toLocaleString('es-AR')}</p><Badge color=\"teal\" dot className=\"mt-1\">pagada</Badge></div></li>))}</ul></div>)}\n      {cuotas.length === 0 && (<div className=\"flex flex-col items-center py-16 text-center\"><div className=\"w-14 h-14 bg-primary-light rounded-2xl flex items-center justify-center mb-4\"><CreditCard size={22} className=\"text-primary\" /></div><p className=\"text-sm font-semibold text-[#1E1B4B]\">Sin cuotas registradas</p></div>)}\n    </div>\n  )\n}\n",
  "src/pages/Asistencia.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getAsistencia } from '../services/portal'\nimport Spinner from '../components/ui/Spinner'\nimport { CalendarCheck, CalendarX } from 'lucide-react'\n\nexport default function Asistencia() {\n  const { alumno } = useAuth()\n  const [registros, setRegistros] = useState([])\n  const [loading, setLoading] = useState(true)\n  useEffect(() => { getAsistencia(alumno.id).then(setRegistros).finally(() => setLoading(false)) }, [alumno.id])\n  if (loading) return <Spinner className=\"mt-20\" />\n  const presentes = registros.filter((r) => r.presente).length\n  const pct = registros.length > 0 ? Math.round((presentes / registros.length) * 100) : null\n  return (\n    <div className=\"px-4 py-5 space-y-4 animate-fade-up\">\n      <h2 className=\"text-base font-bold text-[#1E1B4B]\">Asistencia</h2>\n      {registros.length > 0 && (<div className=\"bg-white rounded-2xl border border-[#EDE9FE] p-5 shadow-card flex items-center justify-between\"><div><p className=\"text-xs text-[#A89FC8] font-medium\">Últimas {registros.length} clases</p><p className=\"text-2xl font-black text-primary mt-0.5\">{pct}%</p><p className=\"text-xs text-[#A89FC8]\">de asistencia</p></div><div className=\"text-right\"><p className=\"text-sm font-semibold text-teal\">{presentes} presentes</p><p className=\"text-sm font-semibold text-red-500 mt-0.5\">{registros.length - presentes} ausentes</p></div></div>)}\n      {registros.length === 0 ? (<div className=\"flex flex-col items-center py-16 text-center\"><div className=\"w-14 h-14 bg-primary-light rounded-2xl flex items-center justify-center mb-4\"><CalendarCheck size={22} className=\"text-primary\" /></div><p className=\"text-sm font-semibold text-[#1E1B4B]\">Sin registros de asistencia</p></div>) : (<ul className=\"space-y-2\">{registros.map((r) => (<li key={r.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] p-4 shadow-card flex items-center justify-between\"><div className=\"flex items-center gap-3\"><div className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${r.presente ? 'bg-teal-light' : 'bg-red-50'}`}>{r.presente ? <CalendarCheck size={15} className=\"text-teal\" /> : <CalendarX size={15} className=\"text-red-500\" />}</div><div><p className=\"text-sm font-semibold text-[#1E1B4B]\">{new Date(r.fecha + 'T00:00:00').toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' })}</p><p className=\"text-xs text-[#A89FC8]\">{r.grupo?.nombre ?? '—'}</p></div></div><span className={`text-xs font-bold ${r.presente ? 'text-teal' : 'text-red-500'}`}>{r.presente ? 'Presente' : 'Ausente'}</span></li>))}</ul>)}\n    </div>\n  )\n}\n",
  "src/pages/Grupos.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getInscripciones } from '../services/portal'\nimport Spinner from '../components/ui/Spinner'\nimport { UsersRound, Clock, Calendar } from 'lucide-react'\n\nexport default function Grupos() {\n  const { alumno } = useAuth()\n  const [inscripciones, setInscripciones] = useState([])\n  const [loading, setLoading] = useState(true)\n  useEffect(() => { getInscripciones(alumno.id).then(setInscripciones).finally(() => setLoading(false)) }, [alumno.id])\n  if (loading) return <Spinner className=\"mt-20\" />\n  return (\n    <div className=\"px-4 py-5 space-y-4 animate-fade-up\">\n      <h2 className=\"text-base font-bold text-[#1E1B4B]\">Mis grupos</h2>\n      {inscripciones.length === 0 ? (<div className=\"flex flex-col items-center py-16 text-center\"><div className=\"w-14 h-14 bg-primary-light rounded-2xl flex items-center justify-center mb-4\"><UsersRound size={22} className=\"text-primary\" /></div><p className=\"text-sm font-semibold text-[#1E1B4B]\">Sin grupos activos</p></div>) : (<ul className=\"space-y-3\">{inscripciones.map((i) => (<li key={i.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] shadow-card overflow-hidden\"><div className=\"p-1\" style={{ background: 'linear-gradient(135deg, #7C3AED, #A78BFA)' }} /><div className=\"p-5\"><div className=\"flex items-start justify-between mb-3\"><div><p className=\"text-base font-bold text-[#1E1B4B]\">{i.grupo?.nombre ?? '—'}</p><p className=\"text-xs text-[#A89FC8] mt-0.5\">{i.grupo?.nivel} · {i.grupo?.disciplina}</p></div><div className=\"w-9 h-9 bg-primary-light rounded-xl flex items-center justify-center shrink-0\"><UsersRound size={15} className=\"text-primary\" /></div></div><div className=\"flex gap-4 mt-3\">{i.grupo?.dia && (<div className=\"flex items-center gap-1.5 text-xs text-[#A89FC8]\"><Calendar size={12} /><span className=\"capitalize\">{i.grupo.dia}</span></div>)}{i.grupo?.horario && (<div className=\"flex items-center gap-1.5 text-xs text-[#A89FC8]\"><Clock size={12} /><span>{i.grupo.horario}</span></div>)}</div></div></li>))}</ul>)}\n    </div>\n  )\n}\n",
  "src/pages/Evaluaciones.jsx": "import { useEffect, useState } from 'react'\nimport { useAuth } from '../context/AuthContext'\nimport { getEvaluaciones } from '../services/portal'\nimport Spinner from '../components/ui/Spinner'\nimport { Star } from 'lucide-react'\n\nfunction notaColor(nota) { return nota >= 8 ? 'text-teal' : nota >= 6 ? 'text-primary' : 'text-amber-500' }\n\nexport default function Evaluaciones() {\n  const { alumno } = useAuth()\n  const [evaluaciones, setEvaluaciones] = useState([])\n  const [loading, setLoading] = useState(true)\n  useEffect(() => { getEvaluaciones(alumno.id).then(setEvaluaciones).finally(() => setLoading(false)) }, [alumno.id])\n  if (loading) return <Spinner className=\"mt-20\" />\n  return (\n    <div className=\"px-4 py-5 space-y-4 animate-fade-up\">\n      <h2 className=\"text-base font-bold text-[#1E1B4B]\">Evaluaciones</h2>\n      {evaluaciones.length === 0 ? (<div className=\"flex flex-col items-center py-16 text-center\"><div className=\"w-14 h-14 bg-primary-light rounded-2xl flex items-center justify-center mb-4\"><Star size={22} className=\"text-primary\" /></div><p className=\"text-sm font-semibold text-[#1E1B4B]\">Sin evaluaciones aún</p></div>) : (<ul className=\"space-y-3\">{evaluaciones.map((e) => (<li key={e.id} className=\"bg-white rounded-2xl border border-[#EDE9FE] p-5 shadow-card\"><div className=\"flex items-start justify-between mb-2\"><div><p className=\"text-sm font-bold text-[#1E1B4B]\">{e.grupo?.nombre ?? '—'}</p><p className=\"text-xs text-[#A89FC8] mt-0.5\">{new Date(e.fecha + 'T00:00:00').toLocaleDateString('es-AR', { day: 'numeric', month: 'long', year: 'numeric' })}</p></div>{e.nota != null && (<div className=\"text-center\"><p className={`text-3xl font-black tabular-nums leading-none ${notaColor(e.nota)}`}>{e.nota}</p><p className=\"text-[10px] text-[#A89FC8] mt-0.5\">/ 10</p></div>)}</div>{e.observaciones && (<p className=\"text-xs text-[#6B5F9E] bg-[#F9F7FF] rounded-xl px-3 py-2.5 mt-3 leading-relaxed\">\"{e.observaciones}\"</p>)}</li>))}</ul>)}\n    </div>\n  )\n}\n"
}

for path, content in FILES.items():
    full = os.path.join(BASE, path)
    os.makedirs(os.path.dirname(full) or BASE, exist_ok=True)
    with open(full, "w", encoding="utf-8") as f:
        f.write(content)

print("Archivos creados en portal-crear/")
print("")
print("Ahora ejecuta en la terminal:")
print("  cd portal-crear")
print("  npm install")
print("  cp .env.example .env")
print("  git init && git branch -m main && git add -A && git commit -m 'feat: portal familiar CREAR'")
print("  git remote add origin https://github.com/mbordon1/PortalCREAR.git")
print("  git push -u origin main")
